'use client';
import { useState, useRef, useEffect } from 'react';
import { formatSqdbHeaderSub } from '../../lib/playlist-stats';
import usePlaylistStats from '../../lib/usePlaylistStats';
import { canonicalizeInterviewLinks, splitTrailingPunctuation } from '../../lib/interview-links';

const SPEAK_TO_TEAM_URL = 'https://www.serialsalescommunity.co?utm_source=sqdb&utm_medium=organic&utm_campaign=sqdb&utm_content=speak_to_team';


const LOGO = "data:image/jpeg;base64,";

// Anonymous per-tab conversation id so logged turns group together. Random,
// not tied to any person; kept in sessionStorage (falls back to memory).
const SESSION_KEY = 'sqdb_session_id';
const SESSION_ID_RE = /^[A-Za-z0-9-]{16,64}$/;
let memorySessionId = null;

function newSessionId() {
  const c = typeof window !== 'undefined' ? window.crypto : null;
  if (c?.randomUUID) return c.randomUUID();
  if (c?.getRandomValues) return Array.from(c.getRandomValues(new Uint8Array(16)), (b) => b.toString(16).padStart(2, '0')).join('');
  return `${Date.now().toString(16)}-${Math.random().toString(16).slice(2)}`.padEnd(16, '0');
}

function getSessionId() {
  try {
    let id = window.sessionStorage.getItem(SESSION_KEY);
    if (!id || !SESSION_ID_RE.test(id)) {
      id = newSessionId();
      window.sessionStorage.setItem(SESSION_KEY, id);
    }
    return id;
  } catch {
    if (!memorySessionId) memorySessionId = newSessionId();
    return memorySessionId;
  }
}

// Opt-in tie-back ids, set by the inline <head> script (lib/early-id-script.js):
// a random first-party browser id and, if the visitor arrived from an email
// link, the beehiiv subscription id. Re-validated here; sent only if well-formed.
const VISITOR_ID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const SUBSCRIBER_REF_RE = /^sub_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

function getTrackingIds() {
  const out = {};
  let vid = null;
  let ref = null;
  try {
    vid = window.localStorage.getItem('tssc_vid');
    ref = window.localStorage.getItem('tssc_subscriber_ref');
  } catch {
    // storage blocked: fall back to the in-memory copies from the head script
  }
  vid = vid || window.__tsscVid || null;
  ref = ref || window.__tsscSubRef || null;
  if (vid && VISITOR_ID_RE.test(vid)) out.visitor_id = vid;
  if (ref && SUBSCRIBER_REF_RE.test(ref)) out.subscriber_ref = ref;
  return out;
}

const SUGGESTIONS = [
  { label: "Tell me about someone like me", prompt: "tell_me" },
  { label: "Give me advice on my situation", prompt: "advice" },
  { label: "How do I break into this space?", prompt: "break_in" },
  { label: "I have a question about TSSC", prompt: "tssc_question" },
];

export default function ChatPage() {
  const playlistStats = usePlaylistStats();
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [awaitingContext, setAwaitingContext] = useState(null);
  const [streamingText, setStreamingText] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);
  const messagesContainerRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, loading]);

  const sendMessage = async (userText) => {
    if (!userText.trim()) return;
    const newMessages = [...messages, { role: 'user', content: userText }];
    setMessages(newMessages);
    setInput('');
    setLoading(true);

    try {
      const res = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        // The server owns the system prompt, model and limits; only the conversation,
        // the anonymous session id and the opt-in tie-back ids are sent.
        body: JSON.stringify({ messages: newMessages, session_id: getSessionId(), ...getTrackingIds() }),
      });
      const data = await res.json();
      // Every YouTube link is rewritten to the canonical watch?v=ID for that member,
      // so a mistyped or stale link from the model never reaches the user.
      const reply = canonicalizeInterviewLinks(data.content?.[0]?.text || 'Something went wrong.');
      
      // Typewriter effect
      setLoading(false);
      setIsStreaming(true);
      setStreamingText('');
      setMessages([...newMessages, { role: 'assistant', content: '' }]);
      
      let i = 0;
      const speed = 12;
      const typeChar = () => {
        if (i < reply.length) {
          const chunk = reply.slice(0, i + 1);
          setStreamingText(chunk);
          setMessages(prev => {
            const updated = [...prev];
            updated[updated.length - 1] = { role: 'assistant', content: chunk };
            return updated;
          });
          i++;
          setTimeout(typeChar, speed);
        } else {
          setIsStreaming(false);
        }
      };
      typeChar();
    } catch (e) {
      setLoading(false);
      setMessages([...newMessages, { role: 'assistant', content: 'Connection error. Please try again.' }]);
    }
  };

  const handleSuggestion = (s) => {
    if (s.prompt === 'tssc_question') {
      setMessages([{ role: 'assistant', content: "What would you like to know about The Serial Sales Community? I can cover the program structure, what\'s included, the process, and what members experience." }]);
    } else if (s.prompt === 'tell_me') {
      setMessages([{ role: 'assistant', content: "Sure, to find someone with a similar background, tell me: what\'s your current work situation? (e.g. job type, industry, hours, income level)" }]);
      setAwaitingContext('tell_me');
    } else if (s.prompt === 'advice') {
      setMessages([{ role: 'assistant', content: "Happy to help. What\'s your current situation, what are you doing now, what\'s your goal, and what\'s the main thing holding you back?" }]);
      setAwaitingContext('advice');
    } else if (s.prompt === 'break_in') {
      setMessages([{ role: 'assistant', content: "A couple quick questions first: do you have any sales experience? And are you looking to do this full-time or start part-time?" }]);
      setAwaitingContext('break_in');
    }
  };

  const handleSubmit = (e) => {
    e?.preventDefault();
    if (awaitingContext) setAwaitingContext(null);
    sendMessage(input);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const isEmpty = messages.length === 0;

  return (
    <div className="sq-app">
      <div className="sq-header">
        <img src={LOGO} alt="TSSC Logo" className="sq-logo" />
        <div className="sq-header-text">
          <span className="sq-header-title">TSSC Success Query</span>
          <span className="sq-header-sub">{formatSqdbHeaderSub(playlistStats)}</span>
        </div>
      </div>

      <div className="sq-messages-wrap" ref={messagesContainerRef}>
        {isEmpty && (
          <div className="sq-empty-state">
            <div className="sq-empty-hero">
              <p className="sq-empty-title">The most successful minds of TSSC in your pocket.</p>
              <p className="sq-empty-sub">Ask anything about breaking into remote appointment setting or closing. Literally anything.</p>
            </div>
            <div className="sq-empty-suggestions">
              {SUGGESTIONS.map((s) => (
                <button key={s.prompt} className="sq-suggestion-chip" onClick={() => handleSuggestion(s)}>
                  {s.label}
                </button>
              ))}
              <a href={SPEAK_TO_TEAM_URL} target="_blank" rel="noopener noreferrer" className="sq-suggestion-chip cta">
                Speak to the TSSC team →
              </a>
            </div>
          </div>
        )}

        {messages.map((m, i) => (
          <div key={i} className={`sq-bubble-row ${m.role}`}>
            <div className={`sq-bubble ${m.role}`}>
              {m.content.split('\n').map((line, j) => {
                // Parse [text](url) markdown links, bare URLs and **bold**.
                // YouTube URLs were already canonicalized in sendMessage.
                const renderBold = (text, keyBase) =>
                  text.split(/\*\*([^*]+)\*\*/g).map((seg, k) =>
                    k % 2 === 1 ? <strong key={`${keyBase}-b${k}`} style={{fontWeight: '600'}}>{seg}</strong> : seg
                  );
                const renderLine = (text) => {
                  const parts = [];
                  let last = 0;
                  let match;
                  const combined = /\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)|(https?:\/\/[^\s]+|serialsalescommunity\.co[^\s]*)/g;
                  while ((match = combined.exec(text)) !== null) {
                    if (match.index > last) parts.push(...renderBold(text.slice(last, match.index), `t${match.index}`));
                    if (match[1] && match[2]) {
                      parts.push(<a key={match.index} href={match[2]} target="_blank" rel="noopener noreferrer" style={{color: '#b6cdde', textDecoration: 'underline', fontWeight: '500'}}>{match[1].replace(/\*\*/g, '')}</a>);
                    } else {
                      // Keep trailing punctuation (". ) ,") out of the href.
                      const [url, trailing] = splitTrailingPunctuation(match[3]);
                      const href = url.startsWith('http') ? url : 'https://' + url;
                      parts.push(<a key={match.index} href={href} target="_blank" rel="noopener noreferrer" style={{color: '#b6cdde', textDecoration: 'underline'}}>{url}</a>);
                      if (trailing) parts.push(trailing);
                    }
                    last = match.index + match[0].length;
                  }
                  if (last < text.length) parts.push(...renderBold(text.slice(last), 'tail'));
                  return parts;
                };
                return (
                  <span key={j}>
                    {renderLine(line)}
                    {j < m.content.split('\n').length - 1 && <br />}
                  </span>
                );
              })}
            </div>
          </div>
        ))}

        {loading && (
          <div className="sq-bubble-row assistant">
            <div className="sq-bubble assistant typing">
              <span className="sq-dot" /><span className="sq-dot" /><span className="sq-dot" />
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="sq-bottom">
        {!isEmpty && (
          <>
            <div className="sq-suggestions-hint-wrap">
              <span className="sq-suggestions-hint">scroll to select a prompt, or type your own.</span>
            </div>
            <div className="sq-suggestions-scroll">
              {SUGGESTIONS.map((s) => (
                <button key={s.prompt} className="sq-suggestion-chip" onClick={() => handleSuggestion(s)}>
                  {s.label}
                </button>
              ))}
              <a href={SPEAK_TO_TEAM_URL} target="_blank" rel="noopener noreferrer" className="sq-suggestion-chip cta">
                Speak to the TSSC team →
              </a>
            </div>
          </>
        )}

        <form className="sq-input-row" onSubmit={handleSubmit}>
          <textarea
            ref={inputRef}
            className="sq-input-box"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Ask anything..."
            rows={1}
          />
          <button type="submit" className="sq-send-btn" disabled={loading || !input.trim()}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
              <path d="M22 2L11 13" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M22 2L15 22L11 13L2 9L22 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </button>
        </form>
      </div>

      <style jsx global>{`
        @import url('https://fonts.googleapis.com/css2?family=Caveat:wght@400&family=DM+Sans:wght@300;400;500;600&family=DM+Mono:wght@400;500&display=swap');

        *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
        /* override the lander's global body padding so the chat fills the screen */
        html, body { padding: 0 !important; }
        body { padding-top: 0 !important; }

        html, body {
          height: 100%;
          width: 100%;
          background: #0d0f12;
          color: #e8eaed;
          font-family: 'DM Sans', sans-serif;
          overflow: hidden;
        }

        .sq-app {
          display: flex;
          flex-direction: column;
          height: 100dvh;
          max-width: 680px;
          margin: 0 auto;
          background: #0d0f12;
        }

        .sq-header {
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 13px 18px 12px;
          border-bottom: 1px solid rgba(182, 205, 222, 0.09);
          background: rgba(13, 15, 18, 0.85);
          backdrop-filter: saturate(140%) blur(8px);
          -webkit-backdrop-filter: saturate(140%) blur(8px);
          flex-shrink: 0;
          z-index: 10;
        }

        @media (min-width: 520px) {
          .sq-header { padding: 15px 28px 14px; }
        }

        .sq-logo {
          width: 40px;
          height: 40px;
          border-radius: 9px;
          object-fit: cover;
        }

        .sq-header-text {
          display: flex;
          flex-direction: column;
          gap: 1px;
        }

        .sq-header-title {
          font-size: 15px;
          font-weight: 600;
          color: #e8eaed;
          letter-spacing: -0.2px;
        }

        .sq-header-sub {
          font-size: 11px;
          color: #b6cdde;
          font-weight: 400;
          opacity: 0.7;
        }

        .sq-messages-wrap {
          flex: 1;
          overflow-y: auto;
          padding: 16px 18px 10px;
          display: flex;
          flex-direction: column;
          gap: 10px;
          -webkit-overflow-scrolling: touch;
          scroll-behavior: smooth;
        }

        @media (min-width: 520px) {
          .sq-messages-wrap { padding: 22px 28px 12px; gap: 12px; }
        }

        .sq-messages-wrap::-webkit-scrollbar { width: 0; }

        .sq-empty-state {
          flex: 1;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: flex-start;
          text-align: left;
          padding: 24px 18px 20px;
          gap: 24px;
          animation: heroIn 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
        }

        .sq-empty-hero {
          display: flex;
          flex-direction: column;
          gap: 13px;
        }

        .sq-empty-title {
          font-size: 29px;
          font-weight: 600;
          color: #e8eaed;
          line-height: 1.14;
          letter-spacing: -0.85px;
          max-width: 330px;
        }

        .sq-empty-sub {
          font-size: 13.5px;
          color: #7a8fa6;
          line-height: 1.6;
          max-width: 310px;
          font-weight: 400;
          letter-spacing: 0.1px;
        }

        .sq-empty-suggestions {
          display: flex;
          flex-wrap: wrap;
          gap: 9px;
          max-width: 440px;
        }

        @keyframes heroIn {
          from { opacity: 0; transform: translateY(12px); }
          to { opacity: 1; transform: translateY(0); }
        }

        @media (min-width: 520px) {
          .sq-empty-state {
            padding: 24px 28px;
            gap: 30px;
          }

          .sq-empty-title {
            font-size: 44px;
            letter-spacing: -1.6px;
            max-width: 520px;
            line-height: 1.07;
          }

          .sq-empty-sub {
            font-size: 15px;
            max-width: 420px;
            color: #7a8fa6;
          }

          .sq-empty-suggestions {
            gap: 10px;
            max-width: 560px;
          }
        }

        .sq-bubble-row {
          display: flex;
          width: 100%;
        }

        .sq-bubble-row.user { justify-content: flex-end; }
        .sq-bubble-row.assistant { justify-content: flex-start; }

        .sq-bubble {
          max-width: 85%;
          padding: 11px 15px;
          border-radius: 18px;
          font-size: 14.5px;
          line-height: 1.58;
          word-break: break-word;
        }

        .sq-bubble-row.assistant .sq-bubble { max-width: 90%; }

        .sq-bubble.user {
          background: #b6cdde;
          color: #0d0f12;
          border-bottom-right-radius: 4px;
          font-weight: 500;
        }

        .sq-bubble.assistant {
          background: #1a1d22;
          color: #d8dce2;
          border-bottom-left-radius: 4px;
          border: 1px solid rgba(255,255,255,0.06);
        }

        .sq-bubble.typing {
          display: flex;
          align-items: center;
          gap: 5px;
          padding: 12px 16px;
        }

        .sq-dot {
          width: 6px;
          height: 6px;
          border-radius: 50%;
          background: #b6cdde;
          opacity: 0.5;
          animation: pulse 1.2s ease-in-out infinite;
        }

        .sq-dot:nth-child(2) { animation-delay: 0.2s; }
        .sq-dot:nth-child(3) { animation-delay: 0.4s; }

        @keyframes pulse {
          0%, 80%, 100% { opacity: 0.3; transform: scale(0.8); }
          40% { opacity: 1; transform: scale(1); }
        }

        .sq-bottom {
          flex-shrink: 0;
          background: #0d0f12;
          padding-bottom: env(safe-area-inset-bottom);
        }

        .sq-suggestions-hint-wrap {
          display: none;
        }
        .sq-suggestions-hint {
          font-family: 'Caveat', cursive;
          font-size: 13px;
          color: rgba(138, 155, 176, 0.5);
          letter-spacing: 0.2px;
          user-select: none;
        }
        @media (max-width: 519px) {
          .sq-suggestions-hint-wrap {
            display: block;
            padding: 0 20px 4px;
            text-align: center;
          }
        }
        .sq-suggestions-scroll {
          display: flex;
          gap: 8px;
          padding: 10px 18px 8px;
          overflow-x: auto;
          -webkit-overflow-scrolling: touch;
          scrollbar-width: none;
          flex-wrap: nowrap;
        }

        .sq-suggestions-scroll::-webkit-scrollbar { display: none; }

        @media (max-width: 519px) {
          .sq-suggestions-scroll {
            -webkit-mask-image: linear-gradient(to right, #000 84%, transparent 100%);
            mask-image: linear-gradient(to right, #000 84%, transparent 100%);
            padding-right: 26px;
          }
        }

        @media (min-width: 520px) {
          .sq-suggestions-scroll {
            flex-wrap: wrap;
            overflow-x: visible;
            padding: 12px 28px 8px;
          }
        }

        .sq-suggestion-chip {
          flex-shrink: 0;
          background: #1a1d22;
          border: 1px solid rgba(182, 205, 222, 0.15);
          color: #b6cdde;
          padding: 8px 15px;
          border-radius: 20px;
          font-size: 13px;
          font-family: 'DM Sans', sans-serif;
          font-weight: 500;
          cursor: pointer;
          white-space: nowrap;
          transition: background 0.15s, border-color 0.15s, transform 0.1s;
        }

        .sq-suggestion-chip:not(.cta):active { transform: scale(0.96); }

        .sq-suggestion-chip:hover, .sq-suggestion-chip:active {
          background: #232730;
          border-color: rgba(182, 205, 222, 0.35);
        }

        .sq-suggestion-chip.cta {
          background: #b6cdde;
          color: #0d0f12;
          border-color: #b6cdde;
          font-weight: 600;
        }

        .sq-suggestion-chip.cta:hover {
          background: #cddae6;
          border-color: #cddae6;
        }

        .sq-input-row {
          display: flex;
          align-items: flex-end;
          gap: 10px;
          padding: 8px 18px 14px;
        }

        @media (min-width: 520px) {
          .sq-input-row { padding: 10px 28px 18px; }
        }

        .sq-input-box {
          flex: 1;
          background: #1a1d22;
          border: 1px solid rgba(182, 205, 222, 0.15);
          border-radius: 22px;
          color: #e8eaed;
          font-family: 'DM Sans', sans-serif;
          font-size: 16px;
          padding: 10px 16px;
          resize: none;
          outline: none;
          max-height: 120px;
          line-height: 1.4;
          transition: border-color 0.15s;
        }

        .sq-input-box:focus {
          border-color: rgba(182, 205, 222, 0.45);
          box-shadow: 0 0 0 3px rgba(182, 205, 222, 0.08);
        }

        .sq-input-box::placeholder { color: #4a5568; }

        .sq-send-btn {
          width: 42px;
          height: 42px;
          border-radius: 50%;
          background: #b6cdde;
          border: none;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          color: #0d0f12;
          flex-shrink: 0;
          transition: opacity 0.15s, transform 0.1s, background 0.15s, box-shadow 0.15s;
        }

        .sq-send-btn:not(:disabled) { box-shadow: 0 4px 14px rgba(182, 205, 222, 0.25); }
        .sq-send-btn:not(:disabled):hover { background: #cddae6; }
        .sq-send-btn:disabled { opacity: 0.3; cursor: default; box-shadow: none; }
        .sq-send-btn:not(:disabled):active { transform: scale(0.92); }

        @media (min-width: 680px) {
          .sq-app {
            border-left: 1px solid rgba(255,255,255,0.05);
            border-right: 1px solid rgba(255,255,255,0.05);
          }
        }

        /* Desktop: full-viewport shell + ChatGPT/Claude-like centered reading column.
           Mobile / tablet rules above stay as-is. */
        @media (min-width: 768px) {
          .sq-app {
            --sq-col: 800px;
            --sq-gutter: max(32px, calc((100% - var(--sq-col)) / 2));
            max-width: none;
            width: 100%;
            border-left: none;
            border-right: none;
          }

          .sq-header {
            padding: 20px var(--sq-gutter) 18px;
          }

          .sq-messages-wrap {
            padding: 28px var(--sq-gutter) 16px;
            gap: 14px;
          }

          .sq-empty-state {
            padding: 40px 0 28px;
            gap: 28px;
            width: 100%;
          }

          .sq-empty-title {
            max-width: 720px;
          }

          .sq-empty-sub {
            max-width: 540px;
          }

          .sq-empty-suggestions {
            max-width: 800px;
          }

          .sq-suggestions-scroll {
            padding: 12px var(--sq-gutter) 10px;
          }

          .sq-input-row {
            padding: 12px var(--sq-gutter) 24px;
            gap: 12px;
          }

          .sq-input-box {
            padding: 13px 18px;
            min-height: 50px;
          }
        }
      `}</style>
    </div>
  );
}
